src='''def transform(grid):
    n = len(grid)
    diagonal_colors = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                d = c - r
                if d in diagonal_colors and diagonal_colors[d] != color:
                    raise ValueError("conflicting colors on a diagonal")
                diagonal_colors[d] = color

    max_period = 2 * n - 1
    for period in range(1, max_period + 1):
        pattern = {}
        consistent = True
        for d, color in diagonal_colors.items():
            residue = d % period
            if residue in pattern and pattern[residue] != color:
                consistent = False
                break
            pattern[residue] = color
        if consistent and len(pattern) == period:
            return [[pattern[(c - r) % period] for c in range(len(grid[0]))]
                    for r in range(n)]
    raise ValueError("could not infer a complete diagonal period")
'''
